      display_name: sanitizeText(data.display_name || data.nombre_completo || data.name || ''),
      birthdate: toDateOnlyYmd(data.birthdate || data.fecha_nacimiento || data.dob || ''),
      sex: sanitizeText(data.sex || data.sexo || data.gender || ''),
