    if(!footer) return null;
    const existing = footer.querySelector('#ag_event_open_patient_btn');
    if(existing){
      els.eventOpenPatientBtn = existing;
      return existing;
    }
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.id = 'ag_event_open_patient_btn';
