      els.consultorio.innerHTML = `<option value="">Todos los consultorios</option><option value="${CONSULTORIO_UNAVAILABLE_VALUE}">${escaped}</option>`;
      els.consultorio.value = CONSULTORIO_UNAVAILABLE_VALUE;
