    if(/^consultorio\s*#\s*\d+$/.test(safe)) return true;
    if(/^#\s*\d+$/.test(safe)) return true;
    if(/^\d+$/.test(safe)) return true;
    if(/^(primer|segundo|tercer|cuarto|quinto|sexto)\s+consultorio$/.test(safe)) return true;
    return false;
